// Make the agent's inputs safe and predictable before querying the database
const j = $json;

// days: a whole number between 1 and 180, default 30
const days = Math.min(Math.max(parseInt(j.days, 10) || 30, 1), 180);

// limit: how many transactions to list, between 1 and 25, default 10
const limit = Math.min(Math.max(parseInt(j.limit, 10) || 10, 1), 25);

// search: plain lowercase text, at most 50 characters
let search = String(j.search ?? '').trim().toLowerCase().slice(0, 50);

// Translate everyday words into the categories used in the data.
// An empty value means "no filter" (show everything).
const synonyms = {
  salary: 'income', paycheck: 'income', payroll: 'income', wages: 'income', pay: 'income', deposit: 'income',
  rent: 'housing', mortgage: 'housing',
  atm: 'cash', withdrawal: 'cash',
  food: 'dining', restaurant: 'dining', restaurants: 'dining', coffee: 'dining',
  gas: 'fuel', petrol: 'fuel',
  bills: 'utilities', bill: 'utilities', electricity: 'utilities', internet: 'utilities', phone: 'utilities',
  subscription: 'subscriptions', fee: 'fees',
  charges: '', charge: '', unrecognized: '', unknown: '', duplicate: '', duplicates: '', all: '', everything: '',
};
if (search in synonyms) search = synonyms[search];

// account_type: only "checking" or "savings" are allowed, otherwise no filter
const acct = String(j.account_type ?? '').trim().toLowerCase();

return {
  json: {
    customer_id: String(j.customer_id ?? '').replace(/\D/g, ''),
    security_answer: String(j.security_answer ?? ''),
    days,
    limit,
    search,
    account_type: ['checking', 'savings'].includes(acct) ? acct : '',
  },
};

// Turn the transactions into a clear answer for the agent
const j = $json;
const input = $('Clean inputs').item.json;

if (!j || !j.customer_id) {
  return { json: { result: 'NOT VERIFIED. The customer ID or security answer did not match. Do not share any account information. Ask the caller to verify again.' } };
}

const txs = (typeof j.transactions === 'string' ? JSON.parse(j.transactions) : j.transactions) || [];

// Spell out a dollar amount the way people say it out loud
const spokenMoney = n => {
  const ones = ['zero','one','two','three','four','five','six','seven','eight','nine','ten','eleven','twelve','thirteen','fourteen','fifteen','sixteen','seventeen','eighteen','nineteen'];
  const tens = ['','','twenty','thirty','forty','fifty','sixty','seventy','eighty','ninety'];
  const under1000 = x => {
    const parts = [];
    if (x >= 100) { parts.push(ones[Math.floor(x / 100)] + ' hundred'); x %= 100; }
    if (x >= 20) { parts.push(tens[Math.floor(x / 10)] + (x % 10 ? '-' + ones[x % 10] : '')); }
    else if (x > 0 || parts.length === 0) { parts.push(ones[x]); }
    return parts.join(' ');
  };
  const words = x => {
    if (x === 0) return 'zero';
    const groups = [[1e9, 'billion'], [1e6, 'million'], [1e3, 'thousand']];
    const parts = [];
    for (const [size, name] of groups) {
      if (x >= size) { parts.push(under1000(Math.floor(x / size)) + ' ' + name); x %= size; }
    }
    if (x > 0) parts.push(under1000(x));
    return parts.join(' ');
  };
  const total = Math.round(Math.abs(Number(n)) * 100);
  const dollars = Math.floor(total / 100);
  const cents = total % 100;
  let s = `${words(dollars)} dollar${dollars === 1 ? '' : 's'}`;
  if (cents) s += ` and ${words(cents)} cent${cents === 1 ? '' : 's'}`;
  return s;
};

// Every amount appears as a number AND in words
// Amounts in words first (to be spoken), with the number in brackets
const money = n => `${spokenMoney(n)} (${Math.abs(Number(n)).toLocaleString('en-US', { style: 'currency', currency: 'USD' })})`;

const when = t => new Date(String(t).slice(0, 19) + 'Z').toLocaleString('en-US', {
  month: 'long', day: 'numeric', hour: 'numeric', minute: '2-digit', timeZone: 'UTC',
});

// Describe which filters were used
const filters = [`last ${input.days} days`];
if (input.search) filters.push(`matching "${input.search}"`);
if (input.account_type) filters.push(`${input.account_type} account only`);

const lines = [];
lines.push(`TRANSACTIONS for customer ${j.customer_id} (${filters.join(', ')}).`);
lines.push('Answer only from this data. Do not calculate new numbers yourself; use the totals given. Only call charges duplicates if they are listed under POSSIBLE DUPLICATE CHARGES. Each transaction has a reference (like T1001259); use it if the caller wants to dispute that transaction, but do not read references aloud unless needed.');

if (!txs.length) {
  lines.push('', 'No transactions found for these filters. Tell the caller none were found, and offer to search a longer period or a different name.');
  return { json: { result: lines.join('\n') } };
}

// Totals are calculated here, never by the agent
const out = txs.filter(t => Number(t.amount) < 0).reduce((s, t) => s + Number(t.amount), 0);
const inn = txs.filter(t => Number(t.amount) > 0).reduce((s, t) => s + Number(t.amount), 0);
lines.push('', `SUMMARY: ${txs.length} transactions found. Total money out: ${money(out)}. Total money in: ${money(inn)}.`);

// Possible duplicates: same account, same merchant, same amount, within 10 minutes
const sorted = [...txs].sort((a, b) => String(a.txn_time).localeCompare(String(b.txn_time)));
const dups = [];
for (let i = 0; i < sorted.length; i++) {
  for (let k = i + 1; k < sorted.length; k++) {
    const a = sorted[i];
    const b = sorted[k];
    const gapMinutes = (new Date(b.txn_time) - new Date(a.txn_time)) / 60000;
    if (gapMinutes > 10) break;
    const sameCharge = a.last4 === b.last4
      && a.description === b.description
      && Number(a.amount) === Number(b.amount)
      && Number(a.amount) < 0;
    if (sameCharge) dups.push({ a, b, gap: Math.round(gapMinutes) });
  }
}
lines.push('', 'POSSIBLE DUPLICATE CHARGES (same merchant, same amount, within 10 minutes):');
if (!dups.length) lines.push('- None found in this period.');
for (const d of dups) {
  lines.push(`- ${d.a.description}, ${money(d.a.amount)}, charged twice on ${when(d.a.txn_time)}, ${d.gap} minutes apart (references ${d.a.txn_id} and ${d.b.txn_id}). The second one is the likely duplicate.`);
}

// List the most recent ones
const shown = txs.slice(0, input.limit);
lines.push('', `MOST RECENT ${shown.length}:`);
for (const t of shown) {
  const amt = Number(t.amount);
  let s = `- ${when(t.txn_time)}: ${t.description}, ${amt < 0 ? 'money out' : 'money in'} ${money(amt)}`;
  s += `, ${t.account_type} account ending ${t.last4}`;
  if (t.card_last4) {
    s += `, paid with debit card ending ${t.card_last4}`;
    if (t.card_status && t.card_status !== 'active') s += ` (that card is now ${t.card_status})`;
  }
  if (t.status !== 'posted') s += `, status ${t.status}`;
  s += ` (reference ${t.txn_id})`;
  lines.push(s + '.');
}
if (txs.length > shown.length) {
  lines.push(`(${txs.length - shown.length} older transactions not listed. Offer to narrow the search if needed.)`);
}

return { json: { result: lines.join('\n') } };
